#!/usr/bin/env bash
# tests/widths/run.sh -- integer-width / f32 semantics against a gcc stdint
# reference.  widths.c (stdint) and widths.km are generated by gen.py; the
# Komodo program must print exactly what the C program prints, on the x86,
# c and (when emcc + node exist) wasm targets.  Sema errors: tests/sema.
set -uo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
root="$(cd "$here/../.." && pwd)"
komodo="${KOMODO:-$root/komodo}"
work="$(mktemp -d)"; trap 'rm -rf "$work"' EXIT
gcc -O0 -w -o "$work/ref" "$here/widths.c" -lm || { echo "FAIL  reference build"; exit 1; }
"$work/ref" > "$work/ref.out"
fail=0
check() {
    local label="$1"; shift
    if got="$("$@" 2>"$work/err")" && diff -q <(printf '%s\n' "$got") "$work/ref.out" >/dev/null; then
        echo "ok   widths/$label"
    else
        echo "FAIL widths/$label"; head -3 "$work/err"
        diff <(printf '%s\n' "$got") "$work/ref.out" | head -8 | sed 's/^/     /'; fail=1
    fi
}
check x86 "$komodo" -q "$here/widths.km"
check c "$komodo" -q -t c "$here/widths.km"
if command -v emcc >/dev/null && command -v node >/dev/null; then
    check wasm "$komodo" -q -t wasm "$here/widths.km"
fi
# FFI marshalling of narrow types (C function in ffi.c, expected output in ffi.expected)
if [[ -f "$here/ffi.km" ]]; then
    if diff -q <("$komodo" -q "$here/ffi.km" 2>&1) "$here/ffi.expected" >/dev/null; then echo "ok   widths/ffi"
    else echo "FAIL widths/ffi"; fail=1; fi
fi
exit $fail
